toolScript:
// --- Chat Parsing Logic ---
        const regexPatterns = [
            /^(\d{1,2}\/\d{1,2}\/\d{2,4}),\s(\d{1,2}:\d{2})\s-\s(.*?):\s(.*)/,
            /^\[(\d{1,2}\/\d{1,2}\/\d{2,4}),\s(\d{1,2}:\d{2}:\d{2})\]\s(.*?):\s(.*)/
        ];
        let charts = {};
        function loadDemo() {
            document.getElementById('upload-section').classList.add('hidden');
            document.getElementById('loading').classList.remove('hidden');
            setTimeout(() => {
                const users = ["You", "Partner"];
                const messages = [];
                let date = new Date();
                date.setFullYear(date.getFullYear() - 1);
                for (let i = 0; i < 5000; i++) {
                    date.setMinutes(date.getMinutes() + Math.floor(Math.random() * 300));
                    messages.push({
                        date: new Date(date),
                        author: users[Math.floor(Math.random() * users.length)],
                        content: "Stochastic simulation message artifact"
                    });
                }
                document.getElementById('loading').classList.add('hidden');
                renderDashboard(messages);
            }, 1000);
        }
        function handleFile(input) {
            const file = input.files[0];
            if (!file) return;
            document.getElementById('upload-section').classList.add('hidden');
            document.getElementById('loading').classList.remove('hidden');
            const reader = new FileReader();
            reader.onload = function (e) {
                const text = e.target.result;
                const messages = parseChat(text);
                document.getElementById('loading').classList.add('hidden');
                if (messages.length > 0) {
                    renderDashboard(messages);
                } else {
                    alert("Analysis Failure: Invalid Transcript Format.");
                    resetTool();
                }
            };
            reader.readAsText(file);
        }
        function parseChat(text) {
            const lines = text.split('\n');
            const messages = [];
            lines.forEach(line => {
                for (let regex of regexPatterns) {
                    const match = line.match(regex);
                    if (match) {
                        const dateParts = match[1].split(/[\/\-]/);
                        const timeParts = match[2].split(':');
                        let year = parseInt(dateParts[2]);
                        if (year < 100) year += 2000;
                        const dateObj = new Date(year, parseInt(dateParts[1]) - 1, parseInt(dateParts[0]), parseInt(timeParts[0]), parseInt(timeParts[1]));
                        if (!isNaN(dateObj)) {
                            messages.push({ date: dateObj, author: match[3], content: match[4] });
                        }
                        break;
                    }
                }
            });
            return messages;
        }
        function renderDashboard(messages) {
            document.getElementById('dashboard').classList.remove('hidden');
            const total = messages.length;
            const authors = {};
            const hourly = new Array(24).fill(0);
            const monthlyData = {};
            let mediaCount = 0;
            let initiations = {};
            messages.forEach((msg, index) => {
                authors[msg.author] = (authors[msg.author] || 0) + 1;
                if (!initiations[msg.author]) initiations[msg.author] = 0;
                if (msg.content.includes('<Media omitted>') || msg.content.includes('image omitted')) mediaCount++;
                hourly[msg.date.getHours()]++;
                const monthKey = `${msg.date.getFullYear()}-${msg.date.getMonth() + 1}`;
                monthlyData[monthKey] = (monthlyData[monthKey] || 0) + 1;
                if (index > 0) {
                    const diffHrs = (msg.date - messages[index - 1].date) / (1000 * 60 * 60);
                    if (diffHrs > 6) initiations[msg.author]++;
                }
            });
            document.getElementById('total-msgs').innerText = total.toLocaleString();
            const daysActive = Math.round((messages[messages.length - 1].date - messages[0].date) / (1000 * 60 * 60 * 24)) || 1;
            document.getElementById('days-active').innerText = daysActive.toLocaleString();
            document.getElementById('avg-daily').innerText = (total / daysActive).toFixed(1);
            document.getElementById('media-count').innerText = mediaCount.toLocaleString();
            const logEl = document.getElementById('analysis-log');
            logEl.innerHTML = `> ANALYZED ${total} SEQUENCE LINES.<br>> IDENTIFIED: ${Object.keys(authors).join(', ')}<br>> SPAN: ${daysActive} DAYS.<br>> BINARY MATCH: SUCCESS.`;
            renderTimeline(monthlyData);
            renderHourly(hourly);
            renderInitiation(initiations);
        }
        function renderTimeline(data) {
            const ctx = document.getElementById('timelineChart').getContext('2d');
            if (charts.timeline) charts.timeline.destroy();
            const sortedKeys = Object.keys(data).sort();
            charts.timeline = new Chart(ctx, {
                type: 'line',
                data: {
                    labels: sortedKeys,
                    datasets: [{
                        data: sortedKeys.map(k => data[k]),
                        borderColor: '#e11d48',
                        backgroundColor: 'rgba(225, 29, 72, 0.05)',
                        tension: 0.4,
                        fill: true,
                        borderWidth: 3,
                        pointRadius: 0
                    }]
                },
                options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } }, scales: { x: { display: false }, y: { grid: { color: '#f1f5f9' }, ticks: { font: { family: 'JetBrains Mono', size: 10 } } } } }
            });
        }
        function renderHourly(data) {
            const ctx = document.getElementById('hourlyChart').getContext('2d');
            if (charts.hourly) charts.hourly.destroy();
            charts.hourly = new Chart(ctx, {
                type: 'bar',
                data: {
                    labels: [...Array(24).keys()].map(h => `${h}h`),
                    datasets: [{
                        data: data,
                        backgroundColor: '#475569',
                        borderRadius: 4
                    }]
                },
                options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } }, scales: { y: { display: false }, x: { grid: { display: false }, ticks: { font: { family: 'JetBrains Mono', size: 9 } } } } }
            });
        }
        function renderInitiation(data) {
            const ctx = document.getElementById('initiationChart').getContext('2d');
            if (charts.init) charts.init.destroy();
            charts.init = new Chart(ctx, {
                type: 'doughnut',
                data: {
                    labels: Object.keys(data),
                    datasets: [{
                        data: Object.values(data),
                        backgroundColor: ['#e11d48', '#0f172a', '#f43f5e', '#334155'],
                        borderWidth: 0
                    }]
                },
                options: { maintainAspectRatio: false, cutout: '70%', plugins: { legend: { position: 'bottom', labels: { font: { weight: 'bold', size: 10 } } } } }
            });
        }
        function resetTool() {
            document.getElementById('dashboard').classList.add('hidden');
            document.getElementById('upload-section').classList.remove('hidden');
            document.getElementById('file-input').value = '';
            Object.values(charts).forEach(c => c.destroy());
            charts = {};
            window.scrollTo({ top: 0, behavior: 'smooth' });
        }
        document.addEventListener('DOMContentLoaded', () => {
            const dropZone = document.getElementById('drop-zone');
            dropZone.addEventListener('dragover', (e) => { e.preventDefault(); dropZone.classList.add('dragover'); });
            dropZone.addEventListener('dragleave', () => { dropZone.classList.remove('dragover'); });
            dropZone.addEventListener('drop', (e) => {
                e.preventDefault();
                dropZone.classList.remove('dragover');
                if (e.dataTransfer.files.length) {
                    document.getElementById('file-input').files = e.dataTransfer.files;
                    handleFile(document.getElementById('file-input'));
                }
            });
        });
